CREATE   PROCEDURE [Moodle].[usp_Insert_mdl_user]
AS
BEGIN

	INSERT INTO [Moodle].[mdl_user]
	(
		[id],
		[auth],
		[confirmed],
		[policyagreed],
		[deleted],
		[suspended],
		[mnethostid],
		[username],
		[aclogin],
		[location_id],
		[manager_id],
		[idnumber],
		[firstname],
		[lastname],
		[gender],
		[email],
		[emailstop],
		[phone1],
		[phone2],
		[institution],
		[department],
		[address],
		[city],
		[country],
		[lang],
		[calendartype],
		[theme],
		[timezone],
		[firstaccess],
		[lastaccess],
		[lastlogin],
		[currentlogin],
		[lastip],
		[secret],
		[picture],
		[description],
		[descriptionformat],
		[mailformat],
		[maildigest],
		[maildisplay],
		[autosubscribe],
		[trackforums],
		[timecreated],
		[timemodified],
		[trustbitmask],
		[lastnamephonetic],
		[firstnamephonetic],
		[middlename],
		[alternatename],
		[moodlenetprofile],
		[updatedinrs]
	)
	SELECT
		src.[id],
		src.[auth],
		src.[confirmed],
		src.[policyagreed],
		src.[deleted],
		src.[suspended],
		src.[mnethostid],
		src.[username],
		src.[aclogin],
		src.[location_id],
		src.[manager_id],
		src.[idnumber],
		src.[firstname],
		src.[lastname],
		src.[gender],
		src.[email],
		src.[emailstop],
		src.[phone1],
		src.[phone2],
		src.[institution],
		src.[department],
		src.[address],
		src.[city],
		src.[country],
		src.[lang],
		src.[calendartype],
		src.[theme],
		src.[timezone],
		src.[firstaccess],
		src.[lastaccess],
		src.[lastlogin],
		src.[currentlogin],
		src.[lastip],
		src.[secret],
		src.[picture],
		src.[description],
		src.[descriptionformat],
		src.[mailformat],
		src.[maildigest],
		src.[maildisplay],
		src.[autosubscribe],
		src.[trackforums],
		src.[timecreated],
		src.[timemodified],
		src.[trustbitmask],
		src.[lastnamephonetic],
		src.[firstnamephonetic],
		src.[middlename],
		src.[alternatename],
		src.[moodlenetprofile],
		src.[updatedinrs]
	FROM [work].[mdl_user] src
		LEFT JOIN [Moodle].[mdl_user] tgt
			ON src.[id] = tgt.[id]
	WHERE tgt.[id] IS NULL

END
